var s=[{title:`Qué hace crecer los músculos`,text:`Los músculos crecen en respuesta a una carga mecánica repetida y a una recuperación suficiente. Los grandes cambios suelen llevar meses o años, no unas pocas sesiones de pesas. Ser fuerte y verse muy musculoso son resultados distintos, y puedes elegir objetivos de entrenamiento que coincidan con lo que quieres.`},{title:`Qué muestran los estudios comparativos`,text:`Un metaanálisis de 2025 encontró que las mujeres y los hombres ganaron un tamaño muscular relativo en general similar con programas comparables de entrenamiento de fuerza, aunque las ganancias absolutas medias de los hombres fueron algo mayores. Eso no es motivo para desanimar a las mujeres de levantar pesas. Demuestra que las mujeres pueden ganar músculo y fuerza reales.`},{title:`Entrena para lo que quieres`,text:`Algunas personas quieren un crecimiento muscular visible. A otras les importan más la fuerza cotidiana, la salud ósea, el rendimiento deportivo o la confianza. Tu volumen de entrenamiento y tu elección de ejercicios pueden seguir esas prioridades. El entrenamiento de fuerza no requiere rutinas de culturismo ni pesos más pesados todos los días.`},{title:`Ejemplo`,text:`Dos sesiones de cuerpo completo a la semana con sentadillas, remos, press y bisagras pueden mejorar la fuerza y la función. Sigue tu rendimiento, y no te preocupes de que un solo entrenamiento vaya a cambiar de pronto tu aspecto.`},{title:`Cómo usar TrainUp`,text:`En Perfil eliges tu objetivo: forma física general, fuerza o acondicionamiento. Tu plan se construye a partir de ese objetivo, tu nivel, tu equipamiento y tus comentarios sobre los entrenamientos, y no promete ninguna forma corporal concreta.`}];var o=[{label:`Revisión sistemática de 2025: crecimiento muscular en hombres y mujeres`,url:`https://pubmed.ncbi.nlm.nih.gov/40028215/`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var n={sections:s,sources:o};export{n as default,s as sections,o as sources};